namespace KiTTYManager.App;

public sealed record HelpEntry(string Section, string Title, string Description);

public static class HelpContent
{
    public const string AllSections = "Все разделы";

    public static IReadOnlyList<HelpEntry> Entries { get; } =
    [
        new("Начало работы", "Что делает менеджер", "Хранит SSH-сессии, строит маршруты через точки входа и промежуточные серверы, открывает KiTTY, WinSCP и веб-панели. Массовые задачи выполняют действия на выбранных серверах. Для первого подключения нужны адрес, SSH-порт, учётная запись и доступный путь к серверу."),
        new("Начало работы", "Новая сессия и импорт KiTTY", "Создайте сессию или выберите импорт из папки portable-сессий KiTTY. Заполните карточку справа и нажмите «Сохранить изменения». Импорт JSON переносит данные другого менеджера; это другая операция, чем чтение папки KiTTY."),
        new("Начало работы", "Умное и прямое открытие", "Двойной клик строит умный маршрут. «Открыть напрямую в KiTTY» использует исходные настройки KiTTY. Флажок «Сначала подключаться напрямую, без JH» относится к выбору маршрута менеджером, а не к открытию исходного файла сессии."),
        new("Начало работы", "Группы и поиск", "Группы и подгруппы организуют сессии. Перетаскивание меняет группу; фильтр помогает найти имя или адрес. Группа сама по себе не задаёт сетевой маршрут: для ограничения используйте «Маршрут через». В общих списках выбора доступны поиск, выбор группы и частичная отметка."),
        new("Сессия", "Название", "Понятное имя, например «Тестовый сервер». Оно не обязано совпадать с DNS-именем. Используется в списках, журналах и именах выгрузок."),
        new("Сессия", "Адрес и SSH-порт", "Введите IP или DNS-имя без ssh://, например 192.0.2.10 или server.example.test. Обычный SSH-порт — 22. Адрес веб-панели задаётся отдельно в таблице веб-интерфейсов."),
        new("Сессия", "Логин и пароль", "Учётная запись для первичного SSH-входа. Например operator. Этот пароль отличается от Root-пароля и passphrase закрытого ключа. Можно использовать пароль, ключ или поддерживаемую сервером комбинацию методов."),
        new("Сессия", "Ключ SSH", "Путь к закрытому ключу PPK/PEM. Относительный путь считается от папки KiTTYManager.exe. Пустой путь допустим. Если сохранённый файл отсутствует, исправьте путь: ключ использоваться не будет, а доступ зависит от остальных методов авторизации. Ключ на удалённой JH — не локальный файл ПК."),
        new("Сессия", "Пароль ключа", "Passphrase, которой защищён закрытый SSH-ключ. Это не пароль учётной записи. Нужна для ключа с шифрованием; незашифрованный ключ не требует этого значения."),
        new("Сессия", "Повышение прав", "Команда перехода к привилегированной учётной записи после SSH-входа: например su -, sudo -i или sudo su -. Если повышение не нужно, оставьте пустым. На сервере должны быть соответствующие права и настройки sudo/su."),
        new("Сессия", "Root-пароль", "Ответ на запрос пароля при повышении прав. Для первичного SSH-входа не используется. При sudo может требоваться пароль текущего пользователя, при su — целевого. Для NOPASSWD оставьте поле пустым."),
        new("Сессия", "Скрипт KiTTY", "Показывает источник импортированного login script. При записи root-данных менеджер изменяет только распознанные конструкции; нестандартный неоднозначный скрипт требует ручной проверки. Сохранение в менеджере и применение изменений к исходной KiTTY — отдельные действия."),
        new("Сессия", "Shell prompt", "Устойчивая подстрока приглашения shell, после которой можно отправить повышение прав. Например operator@server: или $. Это не регулярное выражение. Слишком общий текст может встретиться раньше нужного приглашения."),
        new("Сессия", "Команда KiTTY / Autocommand", "Команда после входа, импортированная из KiTTY, например переход на другой SSH-сервер. Её можно изменить или очистить. Флажок «Не выполнять команду KiTTY при умном подключении» отключает Autocommand для маршрута менеджера, но не отключает повышение прав."),
        new("Сессия", "Маршрут через", "Задаёт промежуточную сессию для доступа к цели; полезно при одинаковых частных IP в разных сетях. «Автоматически» оставляет выбор менеджеру. Альтернативный промежуточный сервер требует подтверждённой связи с целью; группа сама по себе такую защиту не обеспечивает."),
        new("Сессия", "Сначала подключаться напрямую, без JH", "Сначала выполняется попытка SSH с вашего ПК. Если она не проходит, менеджер рассматривает доступные связи и маршруты. Для сервера, доступного непосредственно с ПК, включите этот флажок."),
        new("Сессия", "Резервные адреса: IP и порт", "Дополнительные адреса того же сервера. Пустой IP означает основной хост; порт новой строки — 22. Последний рабочий адрес запоминается отдельно для разных входов и промежуточных серверов."),
        new("Сессия", "Внутренняя подсеть / InternalOnly", "Резервный адрес разрешён только после перехода через другой сервер. На первом переходе от ПК или точки входа он не используется. Это ограничение применимости адреса, а не настройка VPN или маршрута ОС."),
        new("Сессия", "Сохранить изменения и изменения KiTTY", "Сохранение обновляет конфигурацию менеджера. Если включена немедленная запись в KiTTY, изменяется и файл соответствующей встроенной сессии. Иначе отличия можно проверить и применить в «Меню → Изменения KiTTY…»."),
        new("Сессия", "Дублировать и Быстрый дубль", "Обычное дублирование копирует сессию. «Быстрый дубль» открывает отдельный редактор нового сервера: создаёт новый ID, очищает кеши, host key, резервные адреса и веб-панели. После сохранения можно проверить направление от выбранных входных узлов к дублю; отмена проверки не удаляет созданную сессию."),
        new("Сессия", "Открыть в WinSCP", "Открывает SFTP через маршрут менеджера и временный локальный порт. Нужен установленный WinSCP или указанный путь к WinSCP.exe. Не закрывайте менеджер, пока используете его маршрут. В текущей реализации пароль/passphrase передаются аргументами процесса WinSCP."),
        new("Веб-интерфейсы", "Название и URL", "Название — подпись панели. URL — полный адрес с http:// или https://, например https://panel.example.test:8443/. Сессия задаёт доступ к сети сервера, а URL может иметь собственный порт и путь."),
        new("Веб-интерфейсы", "Адрес DNS", "IP, которому должен соответствовать домен из URL внутри этого веб-подключения. Заполните, если имя панели разрешается только во внутренней сети. Пустое поле оставляет обычное разрешение DNS/hosts. Менеджер не редактирует системный файл hosts."),
        new("Веб-интерфейсы", "Логин и пароль панели", "Сохраняются как подсказка для веб-интерфейса. Это не SSH-учётная запись. Менеджер не вводит эти поля автоматически в форму сайта; сохранённые данные исходного профиля Firefox — отдельный механизм."),
        new("Веб-интерфейсы", "Профиль Firefox", "Для каждого открытия создаётся отдельная временная копия исходного профиля. Источник определяется автоматически или выбирается в настройках. Если профиль занят, закройте использующий его Firefox и повторите. Исходные данные не изменяются."),
        new("Веб-интерфейсы", "Что сохраняется после закрытия Firefox", "Новые логины, пароли и исключения сертификатов из временного веб-окна не переносятся обратно в исходный профиль. При удалении копии они теряются. Чтобы использовать заранее сохранённые данные, подготовьте их в исходном профиле до открытия панели."),
        new("Веб-интерфейсы", "Веб-туннель и закрытие окна", "Открытие использует отдельную KiTTY-консоль и локальный SOCKS5-порт. Не закрывайте эту консоль во время работы панели. Настройка «Закрывать консоль веб-туннеля после закрытия Firefox» управляет её завершением после браузера; по умолчанию выключена."),
        new("Точки входа", "Включён и название", "Флажок разрешает менеджеру использовать точку входа при выборе маршрутов. Название — понятная подпись, например «Вход A». Выключение не является командой выключения удалённого сервера."),
        new("Точки входа", "Сессия jumphost", "Сессия SSH, через которую создаётся входной SOCKS5-прокси. Сначала настройте её адрес и авторизацию. Для уже работающего внешнего SOCKS5-сервиса можно указать адрес/порт без привязки запуска к сессии."),
        new("Точки входа", "Адрес и порт SOCKS5", "Адрес SOCKS5-сервиса со стороны вашего ПК, обычно 127.0.0.1 и локальный порт. Это не SSH-порт JH. Готовность определяется ответом SOCKS5, а не только наличием процесса KiTTY или открытого TCP-порта."),
        new("Точки входа", "Запускать сессию, если SOCKS5 недоступен", "Менеджер запускает привязанную jumphost-сессию, когда её SOCKS5 не отвечает. Должны быть заполнены параметры входа и при необходимости OTP. Восстановление собственных процессов не означает управление всеми открытыми вручную консолями."),
        new("Точки входа", "Выбирать свободный локальный SOCKS5-порт автоматически", "Менеджер выбирает свободный порт для запускаемой JH. Удобно при нескольких точках входа на одном ПК. Для внешнего SOCKS5 укажите порт, на котором этот сервис действительно работает."),
        new("Точки входа", "TOTP secret", "Секрет одноразовых кодов Base32 или otpauth:// URI. Это исходный секрет, а не текущие шесть цифр. Если сервер не использует OTP, оставьте пустым. При неверных кодах проверьте часы ПК, секрет, алгоритм, длину и период."),
        new("Точки входа", "Алгоритм, количество цифр и период TOTP", "Должны совпадать с настройками сервера: SHA1/SHA256/SHA512, 6–8 цифр, период в секундах. Типичный вариант — SHA1, 6 цифр, 30 секунд. Поле «Текущий OTP» показывает рассчитанный код, а не пароль SSH."),
        new("Точки входа", "Ожидаемый OTP prompt", "Текст приглашения, после которого отправляется TOTP. Скопируйте устойчивую часть реального запроса сервера. Неверный prompt приводит к ожиданию вместо ввода кода."),
        new("Точки входа", "Команда после входа", "Команда или скрипт, который открывает доступ к внутренним серверам после авторизации на JH. Заполнение не требуется, если доступ уже есть. Настройте команду так, чтобы её повторное выполнение было допустимо."),
        new("Точки входа", "Отправить пароль учётной записи после команды", "Повторяет пароль SSH-учётки после команды доступа, если та просит пароль ещё раз. Это отдельная отправка после входа, а не замена первичной SSH-аутентификации."),
        new("Точки входа", "Ожидаемый prompt пароля", "Приглашение повторного пароля команды доступа. Используйте реальный текст её запроса; не путайте с OTP prompt и Shell prompt обычной сессии."),
        new("Точки входа", "Таймаут скрипта, сек", "Сколько ждать результат команды доступа. Это не таймаут жизни консоли. После истечения проверьте журнал, приглашение пароля и фактическую доступность контрольных серверов."),
        new("Точки входа", "Механизм контрольных серверов", "Менеджер обучается на успешно достигнутых серверах и проверяет, сохранился ли доступ через JH. «Контрольных серверов» ограничивает набор для проверки. Это проверка доступности сети, а не выполнение пользовательской команды на каждом сервере."),
        new("Точки входа", "Перезапуск скрипта по расписанию", "Включите и задайте интервал в минутах, если доступ нужно регулярно продлевать. Срок считается от подтверждённого запуска; простая проверка живого доступа не должна бесконечно откладывать запуск. Пока скрипт работает, повтор параллельно не запускается."),
        new("Точки входа", "Обучено, Состояние скрипта, Консоли и Сбросить", "Статусы помогают отличить запущенную консоль, выполнение команды и подтверждённый доступ. «Сбросить» очищает обученные контрольные серверы и начинает новый отсчёт расписания; это не удаление самой точки входа."),
        new("Маршруты и карта", "Построить связь и проверить доступ", "Проверка выясняет, доступна ли цель через выбранный исходный сервер, и сохраняет успешное направление. Выбирайте источники/цели по реальной сетевой доступности. Сохранённая связь помогает построить следующий маршрут, но не настраивает маршрутизацию на самих серверах."),
        new("Маршруты и карта", "Направления и цвета карты", "A → B не обязательно означает B → A. Стрелки показывают направление, подтверждённые и непроверенные связи различаются оформлением, выделенные дуги — выбор пользователя. Точный результат и использованную точку входа смотрите в таблице «Сохранённые связи»."),
        new("Маршруты и карта", "Выбор пар и Остановить", "Перед массовой проверкой можно исключить направления или серверы только для данного запуска. «Остановить» прекращает работу, сохраняя уже полученные результаты. Закрытие/сворачивание окна прогресса не заменяет эту кнопку."),
        new("Маршруты и карта", "Запомненный маршрут", "Успешный путь и рабочие адреса используются повторно. Фоновые проверки могут найти более короткий доступный путь. Изменение сохранённого предпочтения не переносит уже открытую SSH-консоль на новую цепочку."),
        new("Настройки", "Путь к KiTTY, Firefox и WinSCP", "KiTTY входит в ZIP; Firefox и WinSCP устанавливаются отдельно, если нужны. Для WinSCP пустое поле включает поиск исполняемого файла. Запись portable-сессий ограничена папкой KiTTY рядом с менеджером, независимо от пути запуска KiTTY."),
        new("Настройки", "Автоматический поиск профиля Firefox", "Читает %APPDATA%\\Mozilla\\Firefox\\profiles.ini и выбирает готовый исходный профиль. Если профиль не найден, запустите обычный Firefox один раз либо отключите автопоиск и выберите папку вручную."),
        new("Настройки", "Шаблон профиля Firefox (исходный профиль)", "Несмотря на название поля, здесь выбирается исходная папка Firefox, а не накопительный шаблон менеджера. В ней нужны key4.db и cert9.db. Каждое веб-окно копирует этот источник напрямую; обратной синхронизации нет."),
        new("Настройки", "Таймаут одной попытки подключения", "От 3 до 600 секунд; по умолчанию 10. Ограничивает этап подключения, а не длительность открытой консоли. Сначала проверяйте адреса и маршрут, затем повышайте таймаут для действительно медленной сети."),
        new("Настройки", "Лимит зонда одного адреса", "От 1 до 30 секунд; по умолчанию 4. Короткая проверка конкретного IP:port перед SSH-авторизацией. Отличается от общего таймаута попытки и помогает быстрее перейти к резервному адресу."),
        new("Настройки", "Ожидание восстановления связи в задачах, мин", "От 0 до 99999 минут, по умолчанию 1. Подключение повторяется каждые 10 секунд; после истечения предлагается продлить ожидание или остановиться. Ноль означает отсутствие начального периода ожидания. Для действия с неизвестным результатом может потребоваться подтверждение повтора."),
        new("Настройки", "По крестику скрывать в трей", "Окно скрывается, менеджер продолжает обслуживать маршруты. Для завершения используйте полный выход. Открытая самостоятельная KiTTY может жить отдельно, но цепочка, которую обслуживает менеджер, зависит от его процесса."),
        new("Настройки", "Записывать журнал работы менеджера", "Включает диагностический журнал без перезапуска. По умолчанию выключен. Журнал массовой задачи — отдельный экран. Перед отправкой журналов проверьте имена, адреса и произвольный вывод своих команд."),
        new("Настройки", "Записывать изменения сразу в KiTTY", "После сохранения карточки менеджер обновляет соответствующий файл во встроенной папке KiTTY. Когда флажок выключен, изменения можно просмотреть и применить отдельно в «Изменениях KiTTY»."),
        new("Настройки", "Автоматически доверять новым и изменённым SSH host key", "По умолчанию включено: менеджер принимает новые и изменённые ключи без диалога. Отключите, если хотите вручную сверять отпечатки с администратором. Host key удостоверяет сервер и не является вашим закрытым SSH-ключом."),
        new("Настройки", "Не показывать уведомления об изменениях KiTTY при запуске", "Убирает стартовые уведомления, но не удаляет различия. Они остаются доступны через меню «Изменения KiTTY…»."),
        new("Настройки", "Параллельно проверять две лучшие точки входа", "По умолчанию выключено. Когда подходящие точки уже готовы, конкурирующие проверки могут ускорить выбор рабочего маршрута. Это создаёт дополнительные одновременные SSH-попытки."),
