    public static IReadOnlyList<HelpEntry> Search(string? query, string? section = null)
    {
        var words = (query ?? "").Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries);
        return Entries.Where(entry => words.Length == 0
            ? string.IsNullOrEmpty(section) || section == AllSections || entry.Section == section
            : words.All(word => (entry.Section + " " + entry.Title + " " + entry.Description)
                .Contains(word, StringComparison.OrdinalIgnoreCase))).ToArray();
    }
}
